// Props: every object of the House, painted procedurally. Anchor = bottom-centre unless noted.
import { canvas, shade, woodGrain, rng, roundRect, glowDot, ellipse, poly, box, blotches, strokes, type Ctx } from './util';
import { SYMBOLS } from '../../data/puzzles';

export interface PropArt { canvas: HTMLCanvasElement; ax: number; ay: number }

const WOOD = '#654635', DARK = '#3b281d', MID = '#4d3527', BEIGE = '#b9a58a', WINE = '#6e292d', GREEN = '#3e5145', SLATE = '#445463', LIGHT = '#e6b469', PAPER = '#cfc2a5', IRON = '#3a3a3d', BRASS = '#a88845';

type Painter = (ctx: Ctx, w: number, h: number, v: string, r: () => number) => void;
interface Spec { w: number; h: number; ax?: number; ay?: number; p: Painter }

const legs = (ctx: Ctx, xs: number[], y0: number, y1: number, col: string, lw = 8) => { for (const x of xs) { ctx.fillStyle = col; ctx.fillRect(x - lw / 2, y0, lw, y1 - y0); ctx.fillStyle = 'rgba(0,0,0,0.3)'; ctx.fillRect(x + lw / 2 - 2, y0, 2, y1 - y0); } };
const shadowFloor = (ctx: Ctx, w: number, h: number, sx = 0.45) => { const g = ctx.createRadialGradient(w / 2, h - 4, 2, w / 2, h - 4, w * sx); g.addColorStop(0, 'rgba(0,0,0,0.55)'); g.addColorStop(1, 'rgba(0,0,0,0)'); ctx.save(); ctx.scale(1, 0.16); ctx.fillStyle = g; ctx.beginPath(); ctx.arc(w / 2, (h - 4) / 0.16, w * sx, 0, 7); ctx.fill(); ctx.restore(); };
const frameRect = (ctx: Ctx, x: number, y: number, w: number, h: number, col = '#5c4128', t = 8) => { ctx.fillStyle = col; ctx.fillRect(x, y, w, h); ctx.fillStyle = shade(col, 0.25, 0.7); ctx.fillRect(x, y, w, 2); ctx.fillStyle = shade(col, -0.5); ctx.fillRect(x, y + h - 2, w, 2); ctx.fillStyle = '#141212'; ctx.fillRect(x + t, y + t, w - t * 2, h - t * 2); };
const paper = (ctx: Ctx, x: number, y: number, w: number, h: number, rot: number, col = PAPER) => { ctx.save(); ctx.translate(x, y); ctx.rotate(rot); ctx.fillStyle = col; ctx.fillRect(-w / 2, -h / 2, w, h); ctx.fillStyle = 'rgba(40,30,20,0.35)'; for (let i = 0; i < 4; i++) ctx.fillRect(-w / 2 + 5, -h / 2 + 6 + i * (h / 5), w * 0.7, 1.5); ctx.restore(); };
const flame = (ctx: Ctx, x: number, y: number, s = 1) => { glowDot(ctx, x, y - 4 * s, 14 * s, '#ffcf7a', 0.6); ctx.fillStyle = '#ffe2a0'; ctx.beginPath(); ctx.ellipse(x, y - 5 * s, 3 * s, 7 * s, 0, 0, 7); ctx.fill(); ctx.fillStyle = '#fff7df'; ctx.beginPath(); ctx.ellipse(x, y - 3 * s, 1.4 * s, 3 * s, 0, 0, 7); ctx.fill(); };
const candle = (ctx: Ctx, x: number, y: number, h = 26, w = 9) => { ctx.fillStyle = '#e8dcc0'; ctx.fillRect(x - w / 2, y - h, w, h); ctx.fillStyle = 'rgba(0,0,0,0.2)'; ctx.fillRect(x + w / 2 - 2, y - h, 2, h); flame(ctx, x, y - h); };
const chairShape = (ctx: Ctx, w: number, h: number, col: string) => {
  // side-ish three-quarter chair
  ctx.fillStyle = shade(col, -0.2); ctx.fillRect(w * 0.22, h * 0.06, 8, h * 0.94); ctx.fillRect(w * 0.7, h * 0.06, 8, h * 0.94);
  for (let i = 0; i < 3; i++) { ctx.fillStyle = shade(col, 0.05); ctx.fillRect(w * 0.22, h * 0.1 + i * 26, w * 0.52, 6); }
  box(ctx, w * 0.12, h * 0.52, w * 0.78, 14, col, { edge: 2 });
  legs(ctx, [w * 0.16, w * 0.84], h * 0.52 + 14, h, shade(col, -0.15), 7);
  legs(ctx, [w * 0.3, w * 0.72], h * 0.55, h - 6, shade(col, -0.4), 5);
};
const personSil = (ctx: Ctx, w: number, h: number, col = '#0c0b0d', face = false) => {
  ctx.fillStyle = col;
  ctx.beginPath(); ctx.ellipse(w / 2, h * 0.1, w * 0.13, h * 0.07, 0, 0, 7); ctx.fill();
  ctx.beginPath(); ctx.moveTo(w * 0.3, h * 0.2); ctx.quadraticCurveTo(w / 2, h * 0.15, w * 0.7, h * 0.2); ctx.lineTo(w * 0.78, h * 0.62); ctx.lineTo(w * 0.66, h * 0.64); ctx.lineTo(w * 0.64, h); ctx.lineTo(w * 0.54, h); ctx.lineTo(w * 0.5, h * 0.66); ctx.lineTo(w * 0.46, h); ctx.lineTo(w * 0.36, h); ctx.lineTo(w * 0.34, h * 0.64); ctx.lineTo(w * 0.22, h * 0.62); ctx.closePath(); ctx.fill();
  if (face) ellipse(ctx, w / 2, h * 0.1, w * 0.1, h * 0.055, 'rgba(200,190,175,0.9)');
};

