function keyShape(c: Ctx, x: number, y: number, s: number, col: string, hanging: boolean, lying = false) {
  c.save(); c.translate(x, y); c.scale(s, s);
  if (lying) c.rotate(-0.1); else if (hanging) c.rotate(Math.PI / 2);
  c.strokeStyle = col; c.lineWidth = 4; c.beginPath(); c.arc(0, 0, 7, 0, 7); c.stroke();
  c.fillStyle = col; c.fillRect(6, -2, 26, 4); c.fillRect(24, 2, 3, 6); c.fillRect(29, 2, 3, 4);
  c.restore();
}

let miniDoor: HTMLCanvasElement | null = null;
function paintMini(): HTMLCanvasElement {
  if (miniDoor) return miniDoor;
  const [c, ctx] = canvas(176, 372);
  box(ctx, 0, 0, 176, 372, '#c9bfae');
  for (const [x, y, w, h] of [[20, 24, 60, 150], [96, 24, 60, 150], [20, 190, 60, 160], [96, 190, 60, 160]]) { ctx.fillStyle = 'rgba(0,0,0,0.12)'; ctx.fillRect(x, y, w, h); }
  ellipse(ctx, 150, 196, 8, 8, BRASS);
  miniDoor = c;
  return c;
}

/** Icons for items (inventory / keyring). */
export function paintIcon(icon: string): HTMLCanvasElement {
  const [c, ctx] = canvas(96, 96);
  ctx.translate(48, 48);
  if (icon.startsWith('key_')) {
    const v = icon.slice(4);
    const col = ({ brass_small: '#b8963e', iron: '#5a5a5e', numbered: '#9a8a6a', toothless: '#8a8d90', warm: '#c9743a', bone: '#e0d6c0', half_a: '#9a9a9a', half_b: '#9a9a9a', mended: '#a0a0a0', rusty: '#8a4a2a', master: '#7a7a7e', impossible: '#8a7ab0', unreal: '#6a8ab0', gold: '#d6b25a', glass: '#b8d0d8', service: '#a88845', chapel: '#6a5a4a', clock: '#b8963e', sun: '#c9a449', ephemeral: '#b0aaa0', mutant: '#7a8a5a', plain: '#8a8a7a' } as Record<string, string>)[v] ?? '#9a8a6a';
    ctx.rotate(-0.6);
    ctx.strokeStyle = col; ctx.lineWidth = 7; ctx.beginPath(); ctx.arc(-18, 0, 12, 0, 7); ctx.stroke();
    ctx.fillStyle = col; ctx.fillRect(-6, -4, 40, 8);
    if (v !== 'toothless' && v !== 'half_a') { ctx.fillRect(22, 4, 5, 10); ctx.fillRect(30, 4, 4, 7); }
    if (v === 'half_b') { ctx.clearRect(-40, -20, 36, 40); }
    if (v === 'numbered') { ctx.fillStyle = '#d8cfb8'; ctx.fillRect(-30, 8, 22, 14); ctx.fillStyle = '#222'; ctx.font = 'bold 10px serif'; ctx.fillText('17', -27, 19); }
    if (v === 'warm') { glowDot(ctx, 0, 0, 40, '#ff8a3a', 0.35); }
    if (v === 'gold') glowDot(ctx, -18, -6, 14, '#fff0c0', 0.6);
    return c;
  }
  const r = rng(icon);
  const col = ['#b9a58a', '#8a6a4c', '#6e292d', '#3e5145', '#445463', '#c9a449'][Math.floor(r() * 6)];
  switch (icon) {
    case 'photo': case 'postcard': ctx.fillStyle = '#e8e0cc'; ctx.fillRect(-30, -22, 60, 44); ctx.fillStyle = '#5a5248'; ctx.fillRect(-24, -16, 48, 30); break;
    case 'letter': case 'page': case 'note': case 'list': case 'card': case 'ticket': paper(ctx, 0, 0, 50, 60, -0.1); break;
    case 'drawing': paper(ctx, 0, 0, 54, 64, 0.08, '#e3dac2'); ctx.strokeStyle = '#8a2a22'; ctx.lineWidth = 3; ctx.strokeRect(-10, -18, 20, 34); break;
    case 'tape': box(ctx, -32, -20, 64, 40, '#2a2a2a'); ellipse(ctx, -12, 0, 8, 8, '#ddd'); ellipse(ctx, 12, 0, 8, 8, '#ddd'); break;
    case 'locket': ellipse(ctx, 0, 6, 20, 24, '#c9a449'); ctx.strokeStyle = '#c9a449'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(0, -18); ctx.lineTo(0, -34); ctx.stroke(); break;
    case 'crowbar': ctx.rotate(0.6); ctx.fillStyle = '#6a6d70'; ctx.fillRect(-36, -4, 66, 8); ctx.fillRect(26, -14, 8, 18); break;
    case 'candle': candle(ctx, 0, 30, 44, 14); break;
    case 'bread': ellipse(ctx, 0, 0, 30, 18, '#b88a4a'); break;
    case 'bottle': case 'vial': ctx.fillStyle = 'rgba(120,160,150,0.8)'; roundRect(ctx, -12, -20, 24, 44, 6); ctx.fill(); ctx.fillStyle = '#6a4a2a'; ctx.fillRect(-6, -30, 12, 12); break;
    case 'musicbox': box(ctx, -28, -16, 56, 36, '#6a3a2a'); ctx.fillStyle = '#c9a449'; ctx.fillRect(22, -6, 12, 4); break;
    case 'blueprint': case 'map': ctx.fillStyle = icon === 'map' ? '#cbbd9a' : '#2d4a6a'; ctx.fillRect(-32, -24, 64, 48); ctx.strokeStyle = 'rgba(255,255,255,0.4)'; ctx.strokeRect(-24, -16, 20, 14); ctx.strokeRect(2, 0, 20, 14); break;
    case 'matches': box(ctx, -24, -14, 48, 28, '#8a2a22'); break;
    case 'lantern': ctx.fillStyle = '#3a3a3a'; ctx.fillRect(-16, -26, 32, 50); glowDot(ctx, 0, 0, 24, '#ffcf7a', 0.9); break;
    case 'bandage': box(ctx, -26, -10, 52, 20, '#e0d8c8'); break;
    case 'ring': ctx.strokeStyle = '#d6b25a'; ctx.lineWidth = 6; ctx.beginPath(); ctx.arc(0, 0, 16, 0, 7); ctx.stroke(); break;
    case 'coin': ellipse(ctx, 0, 0, 20, 20, '#b8963e'); ellipse(ctx, 0, 0, 14, 14, '#c9a449'); break;
    case 'doll': ctx.translate(-35, -55); SPECS.doll.p(ctx, 70, 110, '', r); break;
    default: ellipse(ctx, 0, 0, 24, 24, col); ctx.fillStyle = 'rgba(0,0,0,0.25)'; ctx.fillRect(-10, -4, 20, 8);
  }
  return c;
}

const cache = new Map<string, PropArt>();
export function paintProp(kind: string, variant = '', seed = ''): PropArt {
  const key = kind + '|' + variant + '|' + seed;
  const hit = cache.get(key);
  if (hit) return hit;
  const spec = SPECS[kind];
  let art: PropArt;
  if (!spec) {
    const [c, ctx] = canvas(120, 160);
    shadowFloor(ctx, 120, 160); box(ctx, 10, 20, 100, 140, MID);
    art = { canvas: c, ax: 0.5, ay: 1 };
  } else {
    const [c, ctx] = canvas(spec.w, spec.h);
    spec.p(ctx, spec.w, spec.h, variant, rng(kind + variant + seed));
    art = { canvas: c, ax: spec.ax ?? 0.5, ay: spec.ay ?? 1 };
  }
  cache.set(key, art);
  return art;
}

